import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int H, int W, int D,
    int out_H, int out_W, int out_D,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    int in_channels_per_group = in_channels / groups;
    int out_channels_per_group = out_channels / groups;

    long total = (long)batch_size * out_channels * out_H * out_W * out_D;
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long stride_grid = (long)blockDim.x * gridDim.x;

    for (; idx < total; idx += stride_grid) {
        long tmp = idx;
        int d_out = tmp % out_D; tmp /= out_D;
        int w_out = tmp % out_W; tmp /= out_W;
        int h_out = tmp % out_H; tmp /= out_H;
        int co = tmp % out_channels; tmp /= out_channels;
        int b = tmp;

        int group_id = co / out_channels_per_group;
        int ci_start = group_id * in_channels_per_group;

        float acc = 0.0f;

        int d_in = d_out * stride - padding;
        if (d_in >= 0 && d_in < D) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                int h_in = h_out * stride - padding + kh * dilation;
                if (h_in < 0 || h_in >= H) continue;
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int w_in = w_out * stride - padding + kw * dilation;
                    if (w_in < 0 || w_in >= W) continue;

                    for (int ci = 0; ci < in_channels_per_group; ++ci) {
                        int actual_ci = ci_start + ci;
                        long input_idx = ((((long)b * in_channels + actual_ci) * H + h_in) * W + w_in) * D + d_in;
                        long weight_idx = ((((long)co * in_channels_per_group + ci) * kernel_size + kh) * kernel_size + kw) * 1 + 0;
                        acc += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        long output_idx = ((((long)b * out_channels + co) * out_H + h_out) * out_W + w_out) * out_D + d_out;
        output[output_idx] = acc;
    }
}

torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int D = input.size(4);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    int out_H = (H + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_W = (W + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_D = (D + 2 * padding - dilation * (1 - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_H, out_W, out_D}, input.options());

    long total = (long)batch_size * out_channels * out_H * out_W * out_D;
    int threads = 256;
    int blocks = (int)((total + threads - 1) / threads);
    if (blocks < 1) blocks = 1;
    if (blocks > 65535 * 32) blocks = 65535 * 32;

    conv3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        H, W, D,
        out_H, out_W, out_D,
        kernel_size,
        stride,
        padding,
        dilation,
        groups
    );

    return output;
}
"""

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv3d_module = load_inline(
    name="conv3d_module",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a 3D convolution with an asymmetric input and a square kernel
    (kernel_size, kernel_size, 1) using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        out = conv3d_module.conv3d_forward(
            x, weight,
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        )

        if self.bias is not None:
            out = out + self.bias.view(1, -1, 1, 1, 1)

        return out


batch_size = 16
in_channels = 3
out_channels = 64
kernel_size = 3
width = 256
height = 256
depth = 10


def get_inputs():
    x = torch.rand(batch_size, in_channels, height, width, depth)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

